def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marker = next(v for row in grid for v in row if v not in (0, 2, 3, 5, 7))
    # The marked shape spreads through zero cells only by diagonal/orthogonal
    # connectivity, while all nonzero background cells act as barriers.
    seen = set()
    stack = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    while stack:
        r, c = stack.pop()
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if not (dr or dc):
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    stack.append((nr, nc))
    for r, c in seen:
